  ],
  "chunks": [
    {"text": "Had Maya not missed the train", "role": "条件状语从句（虚拟语气，省略if的倒装）", "note": "表示与过去事实相反的假设，相当于 If Maya had not missed the train。"},
    {"text": "she would be attending the interview now", "role": "主句（虚拟语气）", "note": "would be attending 表示现在正在进行的虚拟结果；now 强调与现在事实的对比。"}
  ],
  "key_points": [
    "这是混合虚拟语气：从句与过去事实相反（had not missed），主句与现在事实相反（would be attending now）。",
    "Had Maya not missed 是省略 if 的倒装条件句，正式书面语中常见。"
  ]
}

